    /**
     * Method to retrieve the RateCard via RateCardFetchOneSummary
     * @param 	summary RateCardFetchOneSummary 
     * @return 	RateCardFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public RateCard getRateCard( RateCardFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "RateCardFetchOneSummary arg cannot be null" );
    	
    	RateCard entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	validator.validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a RateCard
        	// --------------------------------------
        	CompletableFuture<RateCard> futureEntity = queryGateway.query(new FindRateCardQuery( new LoadRateCardFilter( summary.getRateCardId() ) ), ResponseTypes.instanceOf(RateCard.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate RateCard with id " + summary.getRateCardId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


